"""Offline, reproducible city-scale demand and vehicle coverage audit report."""
from pathlib import Path
import json,os,html,hashlib,datetime as dt
import numpy as np,pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[2];P=ROOT/'data/processed/three_ward_vehicle_demand_coverage_audit_v1';R=ROOT/'data/exp/feasibility-check/three_ward_vehicle_demand_coverage_audit_v1'
def dump(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def sha(p):
 h=hashlib.sha256()
 with p.open('rb')as f:
  for b in iter(lambda:f.read(8*1024*1024),b''):h.update(b)
 return h.hexdigest()
def main():
 s=json.loads((R/'summary.json').read_text());v=json.loads((R/'validation.json').read_text());assert v['passed'];manifest=json.loads((P/'sources/manifest.json').read_text());assert all(sha(P/'sources'/x['file'])==x['sha256']for x in manifest)
 cats=pd.read_csv(P/'demand_gate_summary.csv').set_index('category');rem=pd.read_csv(P/'remote_geography_summary.csv');cl=pd.read_csv(P/'census_vehicle_class_summary.csv').set_index('road_class');seed=pd.read_csv(P/'core_held_by_ward_direction.csv');ve=pd.read_csv(P/'resident_vehicle_coverage.csv');cv=pd.read_csv(P/'core_demand_conservation.csv');donor=pd.read_csv(P/'positive_fine_person_donor_ledger.csv');clock=pd.read_csv(P/'clock_coverage_audit.csv');timecore=clock[clock.scope.eq('routed_core_touching')].iloc[0]
 existing=pd.read_csv(ROOT/'data/processed/three_ward_normal_vehicle_choice_v1/passage_comparison.csv');xx=existing[existing.arm.eq('U_single')&existing.branch.eq('base_no_remote_remote')&existing.period.eq('daytime12h')&existing.comparison_class.eq('small')];ratio=xx.groupby('road_class')[['predicted','observed']].sum();ratio['model_over_observed']=ratio.predicted/ratio.observed;ratio.to_csv(P/'existing_U_small12h_context.csv',encoding='utf-8-sig')
 plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False,'figure.facecolor':'#f5f8fa'});fig,(ax,bx)=plt.subplots(1,2,figsize=(12,5.2));vals=cv.daily_driver_candidate.to_numpy()/1000;colors=['#367f99','#c28d43','#95a16b','#9a9ca7'];labs=['Routed','No fine donor','Same-zone held','Location unknown'];ax.barh(np.arange(4),vals,color=colors);ax.set_yticks(np.arange(4),labs);ax.invert_yaxis();ax.set(xlim=(0,240),xlabel='Core-touching driver-candidate trips / day (thousands)',title='Core source demand: 248,885 trips / day')
 for i,y in enumerate(vals):ax.text(y+2,i,f'{y:.2f}k',va='center',fontsize=9)
 bx.bar([0,1],[ratio.loc[c,'model_over_observed']*100 for c in ['ordinary','expressway']],color=['#c28d43','#367f99']);bx.axhline(100,ls='--',color='#929da4',lw=1);bx.set_xticks([0,1],['Ordinary (53)','Expressway (32)']);bx.set(ylim=(0,115),ylabel='Existing U / observed small-vehicle passages (%)',title='Existing result, unchanged 85 development screenlines')
 for i,c in enumerate(['ordinary','expressway']):bx.text(i,ratio.loc[c,'model_over_observed']*100+3,f'{ratio.loc[c,"model_over_observed"]:.1%}',ha='center')
 fig.tight_layout(rect=[0,.18,1,1]);fig.text(.5,.035,'Left: distinct source trip records touching the core wards. Right: summed 07:00–19:00 screenline passages.\nThese denominators differ; held trips cannot be subtracted from passage deficits. Small-vehicle counts already exclude large vehicles.\nNo new routing, cost tuning, flood simulation or affected-population calculation.',ha='center',fontsize=8);fig.savefig(R/'coverage_and_count_context.png',dpi=170);plt.close(fig)
 def link(n,label):return f'<a href="{os.path.relpath(P/n,R)}">{html.escape(label)}</a>'
 def tab(frame,rename=None):return '<div class="scroll">'+frame.rename(columns=rename or {}).to_html(index=False,border=0,escape=True,float_format=lambda x:f'{x:,.1f}')+'</div>'
 heldrows=''.join(f'<tr><td>{html.escape(r.ward)}</td><td>{"出发"if r.direction=="departure"else"到达"}</td><td>{r.held_pairs}</td><td>{r.held_daily_driver_candidate:,.0f}</td></tr>'for r in seed.itertuples())
 remoteheld=cats.loc[['held_remote_same_portal','held_remote_different_portal_no_chord'],'daily_driver_candidate'].sum();remoteintra=rem.loc[rem.same_fine_zone,'daily_driver_candidate'].sum();region=ve[ve.scope.eq('whole_region_residents')];goods=region[region.vehicle_class.eq('貨物自動車・軽貨物車')].iloc[0];allreg=region.driver_trips.sum();unkreg=region.driving_unknown_trips.sum()
 doc=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>三区需求与车辆口径核查</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#edf2f5;color:#233e4b;font:16px/1.75 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}}main{{max-width:1120px;margin:32px auto;padding:32px;background:#fff;border-radius:16px}}h1{{font-size:30px;line-height:1.4}}h2{{font-size:22px;margin-top:34px}}p{{margin:14px 0}}a{{color:#146587}}.meta{{color:#657b85;font-size:14px}}.lead{{background:#e9f2f5;border-left:5px solid #367f99;padding:18px}}.note{{background:#fff3df;padding:14px;border-radius:8px}}.cards{{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:22px 0}}.card{{padding:18px;background:#f0f5f6;border-radius:9px}}.big{{font-size:28px;font-weight:700;display:block}}img{{max-width:100%;height:auto;border:1px solid #dce6e9}}.scroll{{overflow:auto}}table{{width:100%;border-collapse:collapse;font-size:14px}}th,td{{padding:10px;border-bottom:1px solid #dce6e9;text-align:left;vertical-align:top}}th{{background:#eef3f5}}code{{overflow-wrap:anywhere}}@media(max-width:700px){{main{{margin:0;padding:20px 14px;border-radius:0}}h1{{font-size:25px}}.cards{{grid-template-columns:1fr}}table{{min-width:650px}}}}</style><main><p class="meta">2026-10-18 JST · 千代田区／中央区／港区及必要外部需求 · 数据核查</p><h1>普通道路缺量：先补需求证据，结束成本微调</h1><div class="lead">已核对暂留OD、外部穿越筛选和车型。168对已知中分区OD的源量与区界可恢复，细分位置仍需假设；区内短途与外部穿越应作为独立条件分支。当前普通道路缺量尚未被解释，不能仅靠放大需求或加入大型车宣称解决。</div><div class="cards"><div class="card"><span class="big">85.6%</span>三区相关源候选已路由</div><div class="card"><span class="big">24,461 次/日</span>168对OD没有正值汽车种子</div><div class="card"><span class="big">{ratio.loc['ordinary','model_over_observed']:.1%}</span>原U组普通道路／实测小型车<br>全部53个普通道路开发断面</div></div><p>本轮未新跑交通分配、未调成本、未追加水动力、未计算受影响人数。原图、OD、原钟点代理、成本和85个观测断面均保持不变；原65＋20均为开发数据。</p><img src="coverage_and_count_context.png" alt="Core demand ledger and unchanged small-vehicle passage comparison"><p class="note">左图是驾驶行程候选；右图是断面通过量。一趟行程可能经过多个断面，也可能一个都不经过。两者不能相减，不能由14.4%的暂留份额推断普通道路缺量能减少多少。</p>
<h2>1. 暂留OD：能补总量与粗尺度位置，不能补造精细起终点</h2><div class="scroll"><table><tr><th>三区相关候选</th><th>次／普通日</th><th>占源量</th><th>接入判断</th></tr><tr><td>已经路由</td><td>212,941.6</td><td>85.56%</td><td>保持原值</td></tr><tr><td>缺正值汽车种子</td><td>24,461.0</td><td>9.83%</td><td>168对中分区OD，全部有官方区界；可保留中分区总量，设计粗尺度接入分支</td></tr><tr><td>同一细分区的区内短途</td><td>6,844.4</td><td>2.75%</td><td>代表点重合造成暂留；可做区内多入口路径情景，不能把原点重复作为通行</td></tr><tr><td>伙伴位置不明</td><td>4,638.0</td><td>1.86%</td><td>只保留总量，不能直接定位</td></tr><tr><td>源量合计</td><td>248,885.0</td><td>100%</td><td>出发＋到达－三区内部，避免内部重复计算</td></tr></table></div><p><b>168对未发现代码映射或读取漏项。</b>615个细分区与中分区的代码、区界、原始d1行号和种子数值全部复核通过。这168对在原细表中有其他交通方式的记录，但没有正值“代表方式为汽车”的细OD种子；不能把它解释为真实世界没有驾车，也不能用铁路／公交乘客直接分配成车辆。官方说明不同分类和分区会各自处理不明值，表间合计可能不同。当前证据无法进一步归因为不明处理、方式定义或样本稀疏中的某一项。</p><p>全区域共有963对已知中分区OD无正值种子，128,231次／日；其中94对连已知细分区组合记录也没有。该区域总量包含远处交通，不能全加给三区。另有427对正值细汽车人次OD没有正值中分区驾驶控制，合计48,132人次／日：它们单列为供体口径不一致，不能当作漏掉的驾驶量补回。</p><div class="scroll"><table><tr><th>区</th><th>方向</th><th>无种子中分区OD对数</th><th>驾驶候选／日</th></tr>{heldrows}</table></div><p>以上出发、到达按源方向分别统计；不用于重复增加三区总量。{link('core_coarse_recovery_candidates.csv','168对粗尺度恢复候选')} · {link('middle_seed_reconciliation.csv','全部中分区／原始细表核对')} · {link('held_intrazonal_pairs.csv','区内暂留账本')}</p>
<h2>2. 外部穿越：筛选没有算错，实际穿越份额仍未知</h2><p>当前条件分支接入295对远端OD、32,112.8次／日，规则是“两端都不在本地代表点池、不同边界门户、两端代表点直线穿过10 km道路范围”。其中仅73对、7,507.4次／日的直线进一步穿过三区本身；这仍只是几何筛选，不能称作真实穿越三区的车辆。</p><div class="scroll"><table><tr><th>远端源OD类别</th><th>对数</th><th>次／日</th><th>解释</th></tr><tr><td>已纳入条件穿越分支</td><td>295</td><td>32,112.8</td><td>未按实际轨迹验证</td></tr><tr><td>同一16扇区门户，暂留</td><td>8,470</td><td>9,918,497.4</td><td>包含远处区内短途；同扇区不等于真实路线不会进出模型</td></tr><tr><td>不同门户，代表点直线未穿域</td><td>9,842</td><td>2,749,903.8</td><td>真实高速或普通道路绕行仍可能不同</td></tr></table></div><p>暂留远端总量约{remoteheld/1e6:.2f}百万次／日，其中{remoteintra/1e6:.2f}百万次是远处同一细分区内的行程，不能全当作缺失的跨区流量。本次重算发现，同门户暂留组的代表点直线也都未穿过10 km范围，未发现规则实现漏掉的直线候选。因此，现有源表不能给出可靠的“应补入三区多少外部车辆”。</p><p><b>可补的是筛选依据与独立分支：</b>保留同门户、不同门户和区内需求的分账；后续若有更大范围机动车OD或边界流量，可约束入域份额和门户分配。没有新证据时，只能预设外部穿越情景，不能把被暂留的区域需求按一个倍数灌入三区，也不需为此扩大水动力范围。</p><p>{link('demand_gate_summary.csv','五类互斥需求账本')} · {link('remote_geography_summary.csv','远端同细分区／同中分区分解')} · {link('remote_gate_by_sector.csv','16扇区门户账本')} · {link('fine_demand_gate_audit.csv','逐OD规则审计')}</p>
<h2>3. 车型：已有货车，缺的是一致的车辆OD口径</h2><p>官方b3三类中，整个调查地区的货物车／轻货物车驾驶记录为{goods.driver_trips:,.0f}次／日，占三类驾驶合计{goods.driver_trips/allreg:.2%}；另有乘用／轻型车14,237,192次、租赁／共享车75,403次。三类驾驶合计15,120,974，与5-3全区域总量及九种目的合计数值一致。5-3文件本身没有写明完整的驾驶过滤与车段端点规则，因此继续标为<b>驾驶行程候选</b>，不升级为完整实测车辆OD。</p><p>这些是<b>居住地</b>统计，不能把三区居民货车占比用在开往三区的外地车辆上。三类另有{unkreg:,.0f}次驾驶状态不明的人次，也不能全部补成车辆。</p><div class="scroll"><table><tr><th>数据</th><th>车型／计数含义</th><th>目前能支持什么</th></tr><tr><td>细尺度d1汽车OD</td><td>代表方式的人次：含乘用车、货物车、租赁车、自用／包租巴士、出租／雇用车</td><td>空间供体；不等于汽车驾驶OD，更不能把出租车乘客加成驾驶数</td></tr><tr><td>b3／5-3驾驶候选</td><td>b3按居住地分三类驾驶／乘坐／不明；5-3按中分区和有料道路使用统计</td><td>保留源控制总量；未提供车型×OD联合分布，未证实商业车及空驶完整性</td></tr><tr><td>道路普查小型车</td><td>乘用／轻型乘用车＋轻货物／小型货物车</td><td>已用于当前普通道路主要评分；不能仅以货车都缺失解释偏差</td></tr><tr><td>道路普查大型车</td><td>巴士、普通货物车和特种车辆</td><td>单列通过量约束；与PT货物车分类不能一一对应</td></tr></table></div><p>在同85个观测断面中，大型车通过量占普通道路{cl.loc['ordinary','large_share']:.2%}、高速{cl.loc['expressway','large_share']:.2%}。<b>原主要评分已经使用小型车，因此大型车未建模不能解释当前小型车口径的缺量。</b>PT货物车又混有不同大小类别，当前驾驶候选也并非严格等同于普查小型车；需要类别对照，不能简单追加一层“全部货车”而重复计算。</p><p>官方PT是居住人口的普通日出行调查，不能由此认证游客／域外居民、出租车空驶、物流及其他商业车辆全部覆盖。现有表没有对应完整车种OD；这些缺口的量目前无法识别。{link('resident_vehicle_coverage.csv','居住地车型边际')} · {link('census_85_vehicle_class_coverage.csv','固定85断面大小车分账')} · {link('official_definition_evidence.csv','官方口径与支持边界')}</p>
<h2>4. 时段和年份：保留未知，不能用来随意抬高高峰</h2><p>三区已路由需求中，按原汽车人次钟点边际推算的未知时刻驾驶候选约{timecore.unknown_clock_conditional_driver_proxy:,.1f}次／日；07–19h约{timecore.known_07_19_driver_proxy:,.1f}次。它们来自原条件分配，不是实测驾驶OD×小时联合表。未知时刻应保留，不能直接填到高峰。2018 PT、2021普查与2026路网的年份和调查对象也不同，尚无证据支持统一增长倍数。</p>
<h2>5. 可补齐清单与下一步</h2><div class="scroll"><table><tr><th>等级</th><th>优先行动</th><th>能得出什么</th><th>不能宣称什么</th></tr><tr><td>源证据足够</td><td>恢复168对中分区总量及官方粗区界；保留现有细种子账本</td><td>24,461次／日有来源的粗尺度OD</td><td>没有精细起终点和真实小时OD</td></tr><tr><td>需要空间假设</td><td>独立设“粗OD接入”和“区内短途”两个增量分支；成本先固定</td><td>分清补需求分别改变哪些道路负载</td><td>不能把改善当作实测路线验证</td></tr><tr><td>需要外部约束或场景</td><td>外部穿越按门户和车型单列，不直接叠加全部区域OD</td><td>得到明确上下情景及与边界观测一致性</td><td>现阶段无法确定应补入多少穿越车辆</td></tr><tr><td>继续保留未知</td><td>4,638次位置不明、车型OD、驾驶时刻、空驶、域外居民</td><td>透明的不完整覆盖</td><td>不能凭边际数还原真实联合OD或受影响人数</td></tr></table></div><p><b>建议下一步：</b>先把24,461次／日已知中分区候选做成独立粗尺度接入方案，另列6,844.4次／日区内短途的条件分支，保持成本固定、分别比较对普通道路与高速的影响；外部穿越和未覆盖车型继续单列。先看补需求是否有解释力，再决定是否需要更大的车辆调查数据。本轮只完成审计，未启动这些分支。</p><p class="note">普通道路正常交通基线仍不满足可信拥堵估计的条件。已知暂留项能提高需求覆盖透明度，却不能证明会填平普通道路断面缺量；与流量相关的后续暴雨拥堵结果仍需标为条件情景。</p>
<h2>复现与核验</h2><p>源代码、来源行号、总量守恒、互斥分账、几何筛选、观测去重、车型以及原输入SHA-256共{v['checks'].__len__()}项核验全部通过。615区界与代码匹配；原始GML/DEM、交通图、成本及原OD没有改写。官方区界读取有GDAL多边形组织警告，本轮只使用原代表点，不进行区界修复或新路线判定；所有615个代码与代表点筛选一致。</p><p>复现：<code>python src/analyses/audit_vehicle_demand_coverage_v1.py</code>，再运行<code>python src/analyses/report_vehicle_demand_coverage_v1.py</code>。报告浏览检查使用<code>validate_vehicle_demand_coverage_browser_v1.cjs</code>。</p><p>{link('audit_contract.json','审计合同')} · {link('input_bindings.json','冻结输入哈希')} · {link('core_demand_conservation.csv','三区候选守恒')} · {link('actionable_gap_inventory.csv','可操作缺口清单')} · {link('clock_coverage_audit.csv','时钟未知账本')} · {link('sources/manifest.json','缓存官方资料')} · <a href="summary.json">机器可读汇总</a> · <a href="validation.json">数值检查</a></p><p><a href="https://www.tokyo-pt.jp/data/H30">2018官方PT表</a> · <a href="https://www.tokyo-pt.jp/person/04_03">官方精度与不明处理说明</a> · <a href="https://www.tokyo-pt.jp/data/01_01">官方交通方式分类</a> · <a href="https://www.mlit.go.jp/road/census/r3/data/pdf/kasyorep.pdf">2021官方道路普查方法</a> · <a href="https://www.openstreetmap.org/copyright">© OpenStreetMap contributors / ODbL</a></p><p class="meta">Framelog：MILI-D-20261018-005。阶段结论只针对当前数据覆盖；本页未作为AnaSOP或Una写作输入。原资料与既有实验保持不变。</p></main></html>'''
 (R/'review.html').write_text(doc)
 files=list(P.rglob('*'))+list(R.glob('*'))+[ROOT/'src/analyses'/n for n in ['audit_vehicle_demand_coverage_v1.py','report_vehicle_demand_coverage_v1.py','validate_vehicle_demand_coverage_browser_v1.cjs']]
 dump(R/'delivery_manifest.json',{'created_utc':dt.datetime.now(dt.timezone.utc).isoformat(),'files':[{'path':str(p.relative_to(ROOT)),'bytes':p.stat().st_size,'sha256':sha(p)}for p in files if p.is_file()and p.name not in ['delivery_manifest.json','review_desktop.png','review_mobile.png','browser_validation.json']]})
 print('Coverage report complete; source caches verified; model inputs unchanged.')
if __name__=='__main__':main()
